CREATE TABLE feature_definitions(definition_id uuid PRIMARY KEY,name text UNIQUE NOT NULL,purpose text NOT NULL,formula text NOT NULL,economic_meaning text NOT NULL,direction integer NOT NULL CHECK(direction IN(-1,1)),frequency text NOT NULL,owner text NOT NULL);
CREATE TABLE feature_versions(version_id uuid PRIMARY KEY,definition_id uuid NOT NULL REFERENCES feature_definitions,version text NOT NULL,code_version text NOT NULL,parameters jsonb NOT NULL,dependency_versions jsonb NOT NULL,min_history integer NOT NULL CHECK(min_history>0),missing_policy text NOT NULL,transform text NOT NULL,active boolean NOT NULL,UNIQUE(definition_id,version));
CREATE TABLE feature_purpose_bindings(purpose text PRIMARY KEY,version_ids jsonb NOT NULL);
CREATE TABLE feature_sets(feature_set_id uuid PRIMARY KEY,purpose text NOT NULL,as_of_date date NOT NULL,decision_at timestamptz NOT NULL,universe_snapshot_id uuid NOT NULL,data_snapshot_id uuid NOT NULL,version_ids jsonb NOT NULL,member_ids jsonb NOT NULL,input_hash char(64) UNIQUE NOT NULL,content_hash char(64) NOT NULL,factor_version text);
CREATE TABLE feature_values(value_id uuid PRIMARY KEY,feature_set_id uuid NOT NULL REFERENCES feature_sets,instrument_id uuid NOT NULL REFERENCES instruments,as_of_date date NOT NULL,version_id uuid NOT NULL REFERENCES feature_versions,data_snapshot_id uuid NOT NULL,value numeric,quality text NOT NULL,input_refs jsonb NOT NULL,steps jsonb NOT NULL,UNIQUE(instrument_id,as_of_date,version_id,data_snapshot_id));
CREATE TABLE feature_events(event_id uuid PRIMARY KEY,event_type text NOT NULL,feature_set_id uuid NOT NULL,occurred_at timestamptz NOT NULL,reasons jsonb NOT NULL);
CREATE TABLE feature_diagnostics(diagnostic_id uuid PRIMARY KEY,version_id uuid NOT NULL REFERENCES feature_versions,as_of_date date NOT NULL,metric text NOT NULL,value numeric NOT NULL,research_only boolean NOT NULL CHECK(research_only));
